 static void Guard(){GetWindowThreadProcessId(GetForegroundWindow(),out var pid);if(pid!=System.Diagnostics.Process.GetCurrentProcess().Id||EditorWindow.focusedWindow!=view)throw new Exception("Stop: Unity Game View lost foreground/focus");GetCursorPos(out var pos);if(Math.Abs(pos.x-expectedCursor.x)>1||Math.Abs(pos.y-expectedCursor.y)>1)throw new Exception("Stop: cursor changed outside owned input; expected "+expectedCursor.x+","+expectedCursor.y+" observed "+pos.x+","+pos.y+" lock="+Cursor.lockState);if((GetAsyncKeyState(2)&0x8000)!=0||(GetAsyncKeyState(4)&0x8000)!=0)throw new Exception("Stop: other mouse button held");}
