 static void SeedBranch(){testedChoice=d.choices.Where(x=>!x.Selected).OrderBy(x=>x.distance).First();ClearPrerequisites();float distance=Mathf.Max(0,testedChoice.distance-16);int segment=0;while(segment<d.route.segments.Length-1&&d.route.SegmentEnd(segment)<distance)segment++;Prop(d,"CurrentSegment",segment);Prop(d,"Distance",distance);d.route.SampleSegment(segment,distance,out var center,out var forward);p.ApplyContinuousRoutePose(center+Vector3.up*d.footOffset,forward,0);Physics.SyncTransforms();Check(!testedChoice.Selected&&testedChoice.OnCurrentFloor&&Mathf.Abs(d.Lane)<.01f,"Directed branch fixture begins unselected with neutral lane",new{testedChoice.name,kind=testedChoice.kind.ToString(),testedChoice.distance,fixtureDistance=distance,realInputRequired=true});}
 static void SeedGoal(){Check(!d.IsTransferring,"Goal fixture begins outside any lift transfer",State());ClearPrerequisites();foreach(var choice in d.choices)if(!choice.Selected)choice.Commit(-1);var goal=d.goals.Single(g=>g.offering);var pc=p.GetComponent<Collider>();var gc=goal.GetComponent<Collider>();int seg=-1;float distance=0,best=float.PositiveInfinity,startAt=0;
  for(int i=0;i<d.route.segments.Length;i++){var r=d.route.segments[i];if(r.floor==goal.floor&&startAt+r.Length>=d.route.Length-40){var span=r.end-r.start;float f=Mathf.Clamp01(Vector3.Dot(gc.bounds.center-r.start,span)/Mathf.Max(.0001f,span.sqrMagnitude));float sq=Vector3.ProjectOnPlane(gc.bounds.center-Vector3.Lerp(r.start,r.end,f),Vector3.up).sqrMagnitude;float progress=startAt+r.Length*f;if(sq<best-.0001f||Mathf.Abs(sq-best)<=.0001f&&progress>distance){best=sq;distance=progress;seg=i;}}startAt+=r.Length;}
  Check(seg>=0&&best<25,"Directed goal projects to final authored route");Prop(d,"CurrentSegment",seg);Prop(d,"Distance",distance);d.route.SampleSegment(seg,distance,out var center,out var forward);p.ApplyContinuousRoutePose(center+Vector3.up*d.footOffset,forward,0);Physics.SyncTransforms();p.transform.position+=gc.bounds.center-pc.bounds.center;p.GetComponent<Rigidbody>().position=p.transform.position;Physics.SyncTransforms();Check(!TimeManager.isGameRunning&&!goal.Claimed&&gc.bounds.Intersects(pc.bounds),"Paused physical goal fixture awaits actual resume input");
 }
