 static void BurstReleaseAndRepeat(){Guard();var cursor=expectedCursor;var foreground=GetForegroundWindow();var target=WindowFromPoint(cursor);string action=label;burstStarted=burstActive=true;burstHeld=held;new Thread(()=>{try{foreach(uint flags in new uint[]{4,2,4}){if(flags==2||burstHeld)Thread.Sleep(60);GetCursorPos(out var observed);if(GetForegroundWindow()!=foreground||WindowFromPoint(cursor)!=target||Math.Abs(observed.x-cursor.x)>1||Math.Abs(observed.y-cursor.y)>1)throw new Exception("Background burst target ownership changed");uint count=SendInput(1,new[]{new NativeInput{type=0,mouse=new Mouse{flags=flags,extra=new UIntPtr(0xC014)}}},Marshal.SizeOf<NativeInput>());if(count!=1)throw new Exception("Background SendInput failed");burstHeld=flags==2;burstEvents.Enqueue(new{action,flags,inserted=count,utc=DateTime.UtcNow.ToString("O"),desktop=new[]{cursor.x,cursor.y},nativeBackgroundThread=true});}}catch(Exception e){burstErrors.Enqueue(e.ToString());if(burstHeld){try{ReleaseOwnedProbeButton();burstHeld=false;}catch(Exception release){burstErrors.Enqueue(release.Message);}}}finally{burstActive=false;}}){IsBackground=true,Name="Cycle14 owned Unity input burst"}.Start();}
 static void BurstSuite(){Probe();Click("burst pause",()=>c.pauseButton.GetComponent<Button>());Add("burst retry baseline",.3,()=>{Check(c.settingsMenuUI.activeInHierarchy&&!TimeManager.isGameRunning,"Pause before true OS double click");loadsBefore=sceneLoads.Count;handleBefore=SceneManager.GetActiveScene().handle;savedCoin=MoneyScript.S.Coin;savedJewel=MoneyScript.S.Jewel;});Click("burst retry",()=>ButtonAt("SettingsMenu/Panel/RunActions/Retry"),true);Add("retry arrives",1.2,()=>{Fresh();Check(sceneLoads.Count==loadsBefore+1&&MoneyScript.S.Coin==savedCoin&&MoneyScript.S.Jewel==savedJewel,"60ms OS retry double click causes one fresh lobby without Story",sceneLoads.Skip(loadsBefore).ToArray());Shot("08-native-burst-retry");});Add("burst goal fresh scene",.2,()=>pendingScene=SceneManager.LoadSceneAsync("ShoeTower"));Add("burst goal fresh lobby",1.2,()=>Fresh());Gesture("burst goal start",new Vector2(70,0));Click("burst goal pause",()=>c.pauseButton.GetComponent<Button>());Add("burst physical goal",.3,()=>SeedGoal());Click("burst goal resume",()=>ButtonAt("SettingsMenu/Panel/RunActions/Resume"));Add("burst result",3.0,()=>{Check(d.GoalClaimed&&CanvasScript.isGameOver&&c.youWinUI.activeInHierarchy,"Burst scenario reaches physical result");loadsBefore=sceneLoads.Count;handleBefore=SceneManager.GetActiveScene().handle;savedCoin=MoneyScript.S.Coin;savedJewel=MoneyScript.S.Jewel;});Click("burst result return",()=>ButtonAt("GameOverScreen/VictoryCard/Continue"),true);Add("result lobby",1.2,()=>{Fresh();Check(sceneLoads.Count==loadsBefore+1&&MoneyScript.S.Coin==savedCoin&&MoneyScript.S.Jewel==savedJewel,"60ms OS result double click causes one fresh lobby and stable reward",sceneLoads.Skip(loadsBefore).ToArray());Shot("09-native-burst-result-return");});}
 public static object BeginBurst(string output){burstOnly=true;return Begin(output);}
