 public static object Begin(string output){if(!EditorApplication.isPlaying||Directory.Exists(output))throw new Exception("Fresh output and Play required");folder=output;Directory.CreateDirectory(folder);view=Resources.FindObjectsOfTypeAll(typeof(EditorWindow).Assembly.GetType("UnityEditor.GameView")).Cast<EditorWindow>().Single();zoom=Get(view,"m_ZoomArea");view.Focus();GetCursorPos(out expectedCursor);SessionState.SetString("Chapter45.Validation14.Cursor",expectedCursor.x+","+expectedCursor.y);if((GetAsyncKeyState(1)&0x8000)!=0)throw new Exception("Initial mouse button held");Bind();steps.Clear();checks.Clear();inputDeferrals.Clear();observations.Clear();sent.Clear();errors.Clear();step=failed=0;frame=-1;held=mousePrimed=false;calibration=Vector2.zero;began=at=EditorApplication.timeSinceStartup;sceneLoads.Clear();expectedHeight=2340;prefix="tall-";if(burstOnly)BurstSuite();else Probe();if(!slowOnly){if(!burstOnly)FullFlow(true);Add("switch to existing short portrait",.3,()=>{view.GetType().GetProperty("selectedSizeIndex",F).SetValue(view,22);view.Repaint();expectedHeight=1920;calibration=Vector2.zero;prefix="short-";pendingScene=SceneManager.LoadSceneAsync("Jamsil");});Add("short lobby settle",1.2,()=>{Bind();Check(Screen.width==1080&&Screen.height==1920,"Existing short portrait selected",State());});if(burstOnly)BurstSuite();else{Probe();FullFlow(false);}}active=true;SceneManager.sceneLoaded+=SceneLoaded;Application.logMessageReceived+=Log;EditorApplication.update+=Tick;Write("conditions.json",new{directedFixtures="Scene load, branch/goal prerequisite and position seed only; no tested start/menu/branch callbacks invoked; other goal prerequisite choices explicitly committed as fixture",input="Windows SendInput; actual UnityEngine.Input and native EventSystem",testedControlCallbacksInvoked=false,otherGoalPrerequisiteChoiceCallbacks=true,engineKeyWrites=false,desktopScope="Foreground Unity GameView only; abort on cursor/focus interference"});return new{started=true,folder,steps=steps.Count};}
 public static object ReleaseOwnedProbeButton(){GetWindowThreadProcessId(GetForegroundWindow(),out var pid);if(pid!=System.Diagnostics.Process.GetCurrentProcess().Id)throw new Exception("Unity foreground required for owned release");uint n=SendInput(1,new[]{new NativeInput{type=0,mouse=new Mouse{flags=4,extra=new UIntPtr(0xC014)}}},Marshal.SizeOf<NativeInput>());return new{released=n==1};}
 static void Log(string m,string s,LogType t){if(t==LogType.Error||t==LogType.Exception||t==LogType.Assert)errors.Add(m+"\n"+s);}
 static void Tick(){if(!active||!EditorApplication.isPlaying)return;if(burstActive)return;if(burstStarted){held=burstHeld;burstStarted=false;while(burstErrors.TryDequeue(out var error))errors.Add(error);if(errors.Count>0){Finish();return;}}EditorApplication.QueuePlayerLoopUpdate();if(frame==Time.frameCount)return;frame=Time.frameCount;try{var mouse=(Vector2)Input.mousePosition;if(Input.GetMouseButtonDown(0)||Input.GetMouseButtonUp(0)||Vector2.Distance(mouse,lastObserved)>1||Input.GetMouseButton(0)){observations.Add(new{frame,label,mouse=V(mouse),expected=mousePrimed?V(expectedGame):null,down=Input.GetMouseButtonDown(0),held=Input.GetMouseButton(0),up=Input.GetMouseButtonUp(0),state=State()});lastObserved=mouse;}if(EditorApplication.timeSinceStartup-began>170)throw new TimeoutException("OS input probe timed out");if(step>=steps.Count){Finish();return;}var s=steps[step];if(EditorApplication.timeSinceStartup-at<s.delay)return;if(pendingScene!=null&&!pendingScene.isDone)return;if((s.name=="retry arrives"||s.name=="result lobby")&&SceneManager.GetActiveScene().handle==handleBefore)return;if(Screen.width!=1080||Screen.height!=expectedHeight){inputDeferrals.Add(new{step=s.name,frame=Time.frameCount,screen=new[]{Screen.width,Screen.height},age=EditorApplication.timeSinceStartup-at});return;}label=s.name;s.action();step++;at=EditorApplication.timeSinceStartup;Write("status.json",new{step,label,total=steps.Count,state=State()});}catch(Exception e){errors.Add(e.ToString());Finish();}}
 static void Finish(){if(held){try{ReleaseOwnedProbeButton();held=false;}catch(Exception e){errors.Add("Owned button release: "+e.Message);}}active=false;EditorApplication.update-=Tick;Application.logMessageReceived-=Log;SceneManager.sceneLoaded-=SceneLoaded;Write("scene-loads.json",sceneLoads);Write("background-os-bursts.json",burstEvents.ToArray());Write("input-deferrals.json",inputDeferrals);Write("observed-input.json",observations);Write("summary.json",new{complete=true,passed=checks.Count-failed,failed,errors,checks,stepsCompleted=step,stepsTotal=steps.Count,seconds=EditorApplication.timeSinceStartup-began,actualOsInput=true,testedControlCallbackInvocation=false,otherGoalPrerequisiteChoiceCallbacks=true,restorationRequired=true});}
}
